#!/usr/bin/env python3
import os
import ssl
from datetime import datetime, timezone

CERT_PATH = "/app/ssl/server.crt"
EXPECTED_CN = "dev-internal.company.local"

if not os.path.isfile(CERT_PATH):
    raise SystemExit(f"Certificate does not exist: {CERT_PATH}")

try:
    cert = ssl._ssl._test_decode_cert(CERT_PATH)
except Exception as exc:
    raise SystemExit(f"Unable to load certificate: {exc}")

common_name = None
for rdn in cert.get("subject", ()): 
    for key, value in rdn:
        if key == "commonName":
            common_name = value
            break
    if common_name:
        break

if not common_name:
    raise SystemExit("Certificate has no Common Name")
if common_name != EXPECTED_CN:
    raise SystemExit(f"Unexpected Common Name: {common_name}")

not_after = cert.get("notAfter")
if not not_after:
    raise SystemExit("Certificate has no expiration date")

try:
    expiration = datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z").replace(tzinfo=timezone.utc)
except ValueError as exc:
    raise SystemExit(f"Unable to parse expiration date: {exc}")

if expiration <= datetime.now(timezone.utc):
    raise SystemExit("Certificate has expired")

print(f"Common Name: {common_name}")
print(f"Expiration Date: {expiration:%Y-%m-%d}")
print("Certificate verification successful")
